    catatan: ['Citra gaun flapper pendek berumbai dengan stoking jaring yang umum di kostum pesta sebagian besar adalah tiruan gaya 1960-an, bukan pakaian sehari-hari 1920-an (dua sumber).'],
    saran: { sulit: 'Sulit', acara: 'Pesta bertema, sesi foto, pertunjukan', hindari: 'Kerja atau acara resmi: terbaca sebagai kostum', hemat: 'Gaun lurus polos, kalung panjang, dan ikat kepala sudah memberi kesan tanpa manik atau umbai' },
    sumber: [['Britannica: flapper', 'https://britannica.com/print/article/209531'], ['Vintage Dancer: pakaian wanita 1920-an', 'https://vintagedancer.com/1920s/1920s-womens-clothing/'], ['Vintage Dancer: mode wanita 1920-an', 'https://vintagedancer.com/1920s/1920s-womens-fashion/'], ['The Mob Museum: mode era Prohibition', 'https://prohibition.themobmuseum.org/the-history/how-prohibition-changed-american-culture/prohibition-fashion/'], ['Fashion-Era: 1920-an', 'https://fashion-era.com/1920s_pictures.htm']],
